void PanelTitleBar::HandleToolBoxItemClick()
{
    if (!mxController)
        return;
    mxController->click();
    mxController->execute(0);
}
IMPL_LINK(PanelTitleBar, ExpandHdl, weld::Expander&, rExpander, void)
{
    if (!mpPanel)
        return;
    mpPanel->SetExpanded(rExpander.get_expanded());
}
